from esm.models.esmc import ESMC
from concurrent.futures import ThreadPoolExecutor
from typing import Sequence

from esm.sdk.api import (
    ESM3InferenceClient,
    ESMProtein,
    ESMProteinError,
    LogitsConfig,
    LogitsOutput,
    ProteinType,
)

# The below sequence is a nucleotide sequence. It should be converted to protein sequence before embedding.
sequence = ""

model = ESMC.from_pretrained("esmc_600m").to("cuda") # or "cpu"

EMBEDDING_CONFIG = LogitsConfig(
    sequence=True, return_hidden_states=True # 37 is the maximum, for 600m model
)


def embed_sequence(model: ESM3InferenceClient, sequence: str = sequence) -> LogitsOutput:
    protein = ESMProtein(sequence=sequence)
    protein_tensor = model.encode(protein)
    output = model.logits(protein_tensor, EMBEDDING_CONFIG)
    return output

output = embed_sequence(model, sequence=sequence)
print(output.hidden_states) # [# hidden states = 36, # sequences = 1, len(sequence) = 12271, # hidden features = 1152]